//
// TableNode      { kind: 'table', path: string[], headered: boolean, map: Map<string, Node> }
// ArrayTableNode { kind: 'arraytable', path: string[], items: TableNode[] }
// ArrayNode      { kind: 'array', items: Node[] }
// ScalarNode     { kind: 'string'|'integer'|'float'|'boolean', value }

export class TableNode {
  constructor(path) {
    this.kind = 'table'
    this.path = path
    this.headered = false
    this.map = new Map()
  }
}

export class ArrayTableNode {
  constructor(path) {
    this.kind = 'arraytable'
    this.path = path
    this.items = []
  }
}

export function makeArray(items) {
  return { kind: 'array', items }
}

export function makeScalar(kind, value) {
  return { kind, value }
}
