{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e3-attempts-t5/cell-TtG9Fr/src/parser.js","content":"import { ParseError } from './errors.js'
import { TableNode, ArrayTableNode, makeArray, makeScalar } from './nodes.js'

const NAME_CHAR = /[A-Za-z0-9_-]/

const INT_PART = '[+-]?[0-9]+(?:_[0-9]+)*'
const FRAC_PART = '\\.[0-9]+(?:_[0-9]+)*'
const EXP_PART = '[eE][+-]?[0-9]+(?:_[0-9]+)*'
const INT_RE = new RegExp(`^${INT_PART}$`)
const FLOAT_RE = new RegExp(`^${INT_PART}(?:${FRAC_PART}${EXP_PART}?|${EXP_PART})$`)

class LineCursor {
  constructor(line, lineNo) {
    this.line = line
    this.lineNo = lineNo
    this.pos = 0
  }

  peek() {
    return this.line[this.pos]
  }

  atEnd() {
    return this.pos >= this.line.length
  }

  skipSpaces() {
    while (!this.atEnd() && (this.line[this.pos] === ' ' || this.line[this.pos] === '\t')) {
      this.pos++
    }
  }

  skipSpacesAndComment() {
    this.skipSpaces()
    const c = this.peek()
    if (c === '#' || c === ';') {
      this.pos = this.line.length
    }
  }

  error(reason) {
    throw new ParseError(this.lineNo, reason)
  }
}

function parseBasicString(cursor) {
  cursor.pos++ // opening quote
  let result = ''
  for (;;) {
    if (cursor.atEnd()) cursor.error('unterminated string')
    const c = cursor.line[cursor.pos]
    if (c === '"') {
      cursor.pos++
      return result
    }
    if (c === '\\') {
      cursor.pos++
      if (cursor.atEnd()) cursor.error('unterminated string')
      const e = cursor.line[cursor.pos]
      switch (e) {
        case '"':
          result += '"'
          cursor.pos++
          break
        case '\\':
          result += '\\'
          cursor.pos++
          break
        case 'n':
          result += '\n'
          cursor.pos++
          break
        case 't':
          result += '\t'
          cursor.pos++
          break
        case 'r':
          result += '\r'
          cursor.pos++
          break
        case '0':
          result += '\0'
          cursor.pos++
          break
        case 'u': {
          const hex = cursor.line.slice(cursor.pos + 1, cursor.pos + 5)
          if (hex.length === 4 && /^[0-9A-Fa-f]{4}$/.test(hex)) {
            result += String.fromCharCode(parseInt(hex, 16))
            cursor.pos += 5
          } else {
            cursor.error('invalid escape \\u')
          }
          break
        }
        default:
          cursor.error('invalid escape \\' + e)
      }
    } else {
      result += c
      cursor.pos++
    }
  }
}

function parseLiteralString(cursor) {
  cursor.pos++ // opening quote
  const start = cursor.pos
  for (;;) {
    if (cursor.atEnd()) cursor.error('unterminated string')
    if (cursor.line[cursor.pos] === "'") {
      const s = cursor.line.slice(start, cursor.pos)
      cursor.pos++
      return s
    }
    cursor.pos++
  }
}

function parseName(cursor) {
  cursor.skipSpacesAndComment()
  if (cursor.atEnd()) cursor.error('expected a name')
  const c = cursor.peek()
  if (c === '"') return parseBasicString(cursor)
  if (c === "'") return parseLiteralString(cursor)
  const start = cursor.pos
  while (!cursor.atEnd() && NAME_CHAR.test(cursor.line[cursor.pos])) cursor.pos++
  if (cursor.pos === start) cursor.error('expected a name')
  return cursor.line.slice(start, cursor.pos)
}

function parseDottedName(cursor) {
  const segments = [parseName(cursor)]
  for (;;) {
    cursor.skipSpacesAndComment()
    if (cursor.peek() === '.') {
      cursor.pos++
      cursor.skipSpacesAndComment()
      segments.push(parseName(cursor))
    } else {
      break
    }
  }
  return segments
}

function normalizeIntText(text) {
  let t = text.replace(/_/g, '')
  if (t[0] === '+') t = t.slice(1)
  return t
}

function parseValue(cursor, pathPrefix) {
  cursor.skipSpacesAndComment()
  if (cursor.atEnd()) cursor.error('expected a value')
  const c = cursor.peek()
  if (c === ',' || c === ']' || c === '}') cursor.error('expected a value')
  if (c === '"') return makeScalar('string', parseBasicString(cursor))
  if (c === "'") return makeScalar('string', parseLiteralString(cursor))
  if (c === '[') return parseArray(cursor, pathPrefix)
  if (c === '{') return parseInlineTable(cursor, pathPrefix)

  const start = cursor.pos
  while (!cursor.atEnd() && ![' ', '\t', ',', ']', '}'].includes(cursor.line[cursor.pos])) {
    cursor.pos++
  }
  const text = cursor.line.slice(start, cursor.pos)
  if (text === 'true') return makeScalar('boolean', true)
  if (text === 'false') return makeScalar('boolean', false)
  if (INT_RE.test(text)) return makeScalar('integer', BigInt(normalizeIntText(text)))
  if (FLOAT_RE.test(text)) return makeScalar('float', Number(text.replace(/_/g, '')))
  cursor.error('invalid value ' + text)
}

function parseArray(cursor, pathPrefix) {
  cursor.pos++ // '['
  const items = []
  cursor.skipSpacesAndComment()
  if (cursor.peek() === ']') {
    cursor.pos++
    return makeArray(items)
  }
  for (;;) {
    const v = parseValue(cursor, pathPrefix)
    items.push(v)
    cursor.skipSpacesAndComment()
    if (cursor.atEnd()) cursor.error('unterminated array')
    const c = cursor.peek()
    if (c === ',') {
      cursor.pos++
      cursor.skipSpacesAndComment()
      if (cursor.atEnd()) cursor.error('unterminated array')
      if (cursor.peek() === ']') {
        cursor.pos++
        break
      }
      continue
    } else if (c === ']') {
      cursor.pos++
      break
    } else {
      cursor.error('trailing text after a value')
    }
  }
  return makeArray(items)
}

function parseInlineTable(cursor, pathPrefix) {
  cursor.pos++ // '{'
  const table = new TableNode(pathPrefix)
  cursor.skipSpacesAndComment()
  if (cursor.peek() === '}') {
    cursor.pos++
    return table
  }
  for (;;) {
    const segments = parseDottedName(cursor)
    cursor.skipSpacesAndComment()
    if (cursor.peek() !== '=') cursor.error('expected = in an inline table')
    cursor.pos++
    const fullPath = table.path.concat(segments)
    const value = parseValue(cursor, fullPath)
    assignDotted(table, segments, value, cursor.lineNo)
    cursor.skipSpacesAndComment()
    if (cursor.atEnd()) cursor.error('unterminated inline table')
    const c = cursor.peek()
    if (c === '}') {
      cursor.pos++
      break
    } else if (c === ',') {
      cursor.pos++
      continue
    } else {
      cursor.error('trailing text after a value')
    }
  }
  return table
}

function assignDotted(targetTable, segments, valueNode, lineNo) {
  let curTable = targetTable
  for (let i = 0; i < segments.length - 1; i++) {
    const seg = segments[i]
    const path = curTable.path.concat(seg)
    const existing = curTable.map.get(seg)
    if (existing === undefined) {
      const t = new TableNode(path)
      curTable.map.set(seg, t)
      curTable = t
    } else if (existing.kind === 'table') {
      curTable = existing
    } else if (existing.kind === 'arraytable') {
      curTable = existing.items[existing.items.length - 1]
    } else {
      throw new ParseError(lineNo, `${path.join('.')} is not a table`)
    }
  }
  const lastSeg = segments[segments.length - 1]
  if (curTable.map.has(lastSeg)) {
    const path = curTable.path.concat(lastSeg)
    throw new ParseError(lineNo, `key ${path.join('.')} is defined twice`)
  }
  curTable.map.set(lastSeg, valueNode)
}

function parseHeader(cursor) {
  cursor.skipSpaces()
  cursor.pos++ // '['
  let isArray = false
  if (cursor.peek() === '[') {
    isArray = true
    cursor.pos++
  }
  cursor.skipSpacesAndComment()
  const segments = parseDottedName(cursor)
  cursor.skipSpacesAndComment()
  if (cursor.atEnd() || cursor.peek() !== ']') cursor.error('unterminated table header')
  cursor.pos++
  if (isArray) {
    if (cursor.peek() !== ']') cursor.error('unterminated table header')
    cursor.pos++
  }
  cursor.skipSpacesAndComment()
  if (!cursor.atEnd()) cursor.error('trailing text after a table header')
  return { segments, isArray }
}

function processHeader(doc, segments, isArray, lineNo) {
  let curTable = doc.root
  for (let i = 0; i < segments.length - 1; i++) {
    const seg = segments[i]
    const path = curTable.path.concat(seg)
    const existing = curTable.map.get(seg)
    if (existing === undefined) {
      const t = new TableNode(path)
      curTable.map.set(seg, t)
      curTable = t
    } else if (existing.kind === 'table') {
      curTable = existing
    } else if (existing.kind === 'arraytable') {
      curTable = existing.items[existing.items.length - 1]
    } else {
      throw new ParseError(lineNo, `${path.join('.')} is not a table`)
    }
  }
  const lastSeg = segments[segments.length - 1]
  const lastPath = curTable.path.concat(lastSeg)
  const existing = curTable.map.get(lastSeg)
  if (!isArray) {
    if (existing === undefined) {
      const t = new TableNode(lastPath)
      t.headered = true
      curTable.map.set(lastSeg, t)
      doc.current = t
    } else if (existing.kind === 'table') {
      if (existing.headered) throw new ParseError(lineNo, `table ${lastPath.join('.')} is defined twice`)
      existing.headered = true
      doc.current = existing
    } else {
      throw new ParseError(lineNo, `${lastPath.join('.')} is not a table`)
    }
  } else {
    if (existing === undefined) {
      const arr = new ArrayTableNode(lastPath)
      const t = new TableNode(lastPath)
      arr.items.push(t)
      curTable.map.set(lastSeg, arr)
      doc.current = t
    } else if (existing.kind === 'arraytable') {
      const t = new TableNode(lastPath)
      existing.items.push(t)
      doc.current = t
    } else {
      throw new ParseError(lineNo, `${lastPath.join('.')} is not an array of tables`)
    }
  }
}

function processAssignmentLine(doc, line, lineNo) {
  const cursor = new LineCursor(line, lineNo)
  cursor.skipSpaces()
  let firstSeg
  try {
    firstSeg = parseName(cursor)
  } catch (e) {
    if (e instanceof ParseError) throw new ParseError(lineNo, 'expected key = value')
    throw e
  }
  const segments = [firstSeg]
  for (;;) {
    cursor.skipSpacesAndComment()
    if (cursor.peek() === '.') {
      cursor.pos++
      cursor.skipSpacesAndComment()
      segments.push(parseName(cursor))
    } else {
      break
    }
  }
  cursor.skipSpacesAndComment()
  if (cursor.peek() !== '=') cursor.error('expected key = value')
  cursor.pos++
  const fullPath = doc.current.path.concat(segments)
  const value = parseValue(cursor, fullPath)
  cursor.skipSpacesAndComment()
  if (!cursor.atEnd()) cursor.error('trailing text after a value')
  assignDotted(doc.current, segments, value, lineNo)
}

function isBlankOrComment(line) {
  for (let i = 0; i < line.length; i++) {
    const c = line[i]
    if (c === ' ' || c === '\t') continue
    return c === '#' || c === ';'
  }
  return true
}

export function parseDocument(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const doc = { root: new TableNode([]), current: null }
  doc.current = doc.root

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i]
    const lineNo = i + 1
    if (isBlankOrComment(line)) continue

    let firstNonSpace = ''
    for (let j = 0; j < line.length; j++) {
      const c = line[j]
      if (c === ' ' || c === '\t') continue
      firstNonSpace = c
      break
    }

    if (firstNonSpace === '[') {
      const cursor = new LineCursor(line, lineNo)
      const { segments, isArray } = parseHeader(cursor)
      processHeader(doc, segments, isArray, lineNo)
    } else {
      processAssignmentLine(doc, line, lineNo)
    }
  }

  return doc.root
}
"}

