    this.line = line
    this.lineNo = lineNo
    this.pos = 0
  }

  peek() {
    return this.line[this.pos]
  }

  atEnd() {
    return this.pos >= this.line.length
  }

  skipSpaces() {
    while (!this.atEnd() && (this.line[this.pos] === ' ' || this.line[this.pos] === '\t')) {
      this.pos++
    }
  }

  skipSpacesAndComment() {
    this.skipSpaces()
    const c = this.peek()
    if (c === '#' || c === ';') {
