        case '"':
          result += '"'
          cursor.pos++
          break
        case '\\':
          result += '\\'
          cursor.pos++
          break
        case 'n':
          result += '\n'
          cursor.pos++
          break
        case 't':
          result += '\t'
          cursor.pos++
          break
        case 'r':
